// Builds the app registry from the manifests under src/apps/<id>/manifest.ts.
//
//   node scripts/gen-apps.mjs            writes the two generated files
//   node scripts/gen-apps.mjs --check    fails when they are out of date (pnpm check)
//
// A new app is one folder with one manifest.ts (see src/apps/README.md). This
// script lists the folders into
//   src/apps/registry.gen.ts   the manifests — plain data, safe for the server
//   src/apps/loaders.gen.ts    the lazy component imports — client only
// so TypeScript sees every app id and the bundler sees every import. It runs by
// itself when `next dev` / `next build` starts and, in dev, whenever a manifest
// is added or removed, so nobody has to remember it.
//
// Manifests are plain TypeScript with type-only imports, so Node loads them
// directly (the same way check-pure.mjs loads the other pure modules).
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const APPS_DIR = path.join(ROOT, 'src/apps');
const REGISTRY = path.join(APPS_DIR, 'registry.gen.ts');
const LOADERS = path.join(APPS_DIR, 'loaders.gen.ts');
const ID = /^[a-z][a-z0-9]*$/;

const HEADER = '// GENERATED by scripts/gen-apps.mjs from src/apps/*/manifest.ts — do not edit.\n// It is refreshed when `next dev` / `next build` starts, and by `pnpm verify`.\n';

function manifestDirs() {
	return fs
		.readdirSync(APPS_DIR, { withFileTypes: true })
		.filter((e) => e.isDirectory() && fs.existsSync(path.join(APPS_DIR, e.name, 'manifest.ts')))
		.map((e) => e.name)
		.sort();
}

/** `./File` is relative to the app's folder; anything else is an alias path. */
const modulePath = (dir, mod) => (mod.startsWith('./') ? `@/apps/${dir}/${mod.slice(2)}` : mod);

function resolveSource(spec) {
	const base = spec.startsWith('@/') ? path.join(ROOT, 'src', spec.slice(2)) : spec;
	return ['.ts', '.tsx', '/index.ts', '/index.tsx'].some((ext) => fs.existsSync(base + ext));
}

/**
 * Loads a manifest through Node's TypeScript support. package.json declares no
 * module type, so Node prints a once-per-file "reparsing as ES module" warning
 * for each manifest; that one warning is not worth showing on every dev start.
 */
async function loadManifest(dir) {
	const url = pathToFileURL(path.join(APPS_DIR, dir, 'manifest.ts')).href + `?t=${Date.now()}`;
	const emit = process.emitWarning;
	process.emitWarning = (warning, ...rest) => {
		if (!String(warning?.message ?? warning).includes('Module type of file')) emit.call(process, warning, ...rest);
	};
	try {
		return (await import(url)).default;
	} finally {
		process.emitWarning = emit;
	}
}

async function readManifest(dir) {
	const manifest = await loadManifest(dir);
	const fail = (msg) => {
		throw new Error(`src/apps/${dir}/manifest.ts: ${msg}`);
	};
	if (!manifest || typeof manifest !== 'object') fail('the default export must be the manifest object');
	if (manifest.id !== dir) fail(`id "${manifest.id}" must equal the folder name "${dir}"`);
	if (!ID.test(dir)) fail('the id must be lower-case letters and digits, starting with a letter');
	const p = manifest.permission;
	if (!p?.ad || !p.kullan || !p.yonet) fail('permission needs ad, kullan and yonet (every app is something a role grants)');
	if (manifest.window) {
		for (const key of ['title', 'shortTitle', 'description', 'en', 'category', 'icon', 'accentColor', 'component']) {
			if (!manifest[key]) fail(`"${key}" is required for an app with a window`);
		}
		const { module, export: name } = manifest.component;
		if (!module || !name) fail('component needs module and export');
		if (!resolveSource(modulePath(dir, module))) fail(`component module "${module}" not found`);
	}
	return manifest;
}

/** The contents of both generated files. */
export async function renderApps() {
	const dirs = manifestDirs();
	const manifests = [];
	for (const dir of dirs) manifests.push(await readManifest(dir));

	const registry =
		HEADER +
		dirs.map((dir, i) => `import m${i} from './${dir}/manifest.ts';`).join('\n') +
		`\n\n/** Every app manifest, by folder name. */\nexport const MANIFESTS = [${dirs.map((_, i) => `m${i}`).join(', ')}] as const;\n`;

	const windowed = dirs.filter((_, i) => manifests[i].window);
	const loaders =
		HEADER +
		"import type { ComponentType } from 'react';\nimport type { AppID } from '@/types/workspace';\n\n" +
		'/** How each app\'s component is loaded — the registry wraps these in lazy components. */\n' +
		'export const APP_LOADERS: Record<AppID, () => Promise<ComponentType>> = {\n' +
		windowed
			.map((dir) => {
				const { module, export: name } = manifests[dirs.indexOf(dir)].component;
				return `\t${dir}: () => import('${modulePath(dir, module)}').then((m) => m.${name}),`;
			})
			.join('\n') +
		'\n};\n';
	return { [REGISTRY]: registry, [LOADERS]: loaders };
}

/** Writes the generated files (only when they changed). Returns the files it touched. */
export async function generateApps() {
	const files = await renderApps();
	const touched = [];
	for (const [file, text] of Object.entries(files)) {
		if (fs.existsSync(file) && fs.readFileSync(file, 'utf8') === text) continue;
		fs.writeFileSync(file, text);
		touched.push(path.relative(ROOT, file));
	}
	return touched;
}

/** Dev only: regenerates when a manifest folder is added, removed or edited. */
export function watchApps(onError = console.error) {
	let timer = null;
	const run = () => {
		clearTimeout(timer);
		timer = setTimeout(() => generateApps().catch(onError), 150);
	};
	try {
		return fs.watch(APPS_DIR, { recursive: true }, (_event, name) => {
			if (name && /(^|[\\/])manifest\.ts$|^[^\\/.]+$/.test(name)) run();
		});
	} catch {
		return null;
	}
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
	try {
		if (process.argv.includes('--check')) {
			const files = await renderApps();
			const stale = Object.entries(files)
				.filter(([file, text]) => !fs.existsSync(file) || fs.readFileSync(file, 'utf8') !== text)
				.map(([file]) => path.relative(ROOT, file));
			if (stale.length) {
				console.error(`gen-apps: ${stale.join(', ')} out of date — run \`node scripts/gen-apps.mjs\``);
				process.exit(1);
			}
			console.log(`gen-apps: ${manifestDirs().length} manifests, generated files up to date`);
		} else {
			const touched = await generateApps();
			console.log(touched.length ? `gen-apps: wrote ${touched.join(', ')}` : 'gen-apps: up to date');
		}
	} catch (error) {
		console.error(error.message);
		process.exit(1);
	}
}
